// Prepare input for AI Agent from webhook body
const body = $input.item.json.body || {};
const query = body.query || body.message || body.text || '';

if (!query) {
  return { json: { error: 'Missing query parameter in request body' } };
}

return {
  json: {
    chatInput: query,
    session_id: body.session_id || 'webhook-' + Date.now(),
    metadata: {
      source: 'webhook',
      timestamp: new Date().toISOString(),
      user_id: body.user_id || null,
    }
  }
};

// Format the agent response for API consumers
const agentOutput = $input.item.json;

return {
  json: {
    success: true,
    response: agentOutput.output || agentOutput.text || agentOutput,
    agent: 'knowledge',
    timestamp: new Date().toISOString()
  }
};

// MCP Tool: search_knowledge
// Auto-generated by deploy-individual-tools.mjs
const query = $input.item.json.query || $input.item.json || '';
let args;
try {
  args = typeof query === 'string' ? JSON.parse(query) : query;
} catch {
  args = typeof query === 'string' && query.length > 0 ? { query } : {};
}

const mcpUrl = ($env?.AISHA_POSTGREST_URL || 'https://api.backend.id3a.cz') + '/functions/v1/mcp-knowledge-server';
const token = $env?.AISHA_ACCESS_TOKEN || $env?.AISHA_KEYCLOAK_ACCESS_TOKEN || '';

const res = await fetch(mcpUrl, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Authorization': 'Bearer ' + token
  },
  body: JSON.stringify({
    jsonrpc: '2.0',
    id: Date.now(),
    method: 'tools/call',
    params: { name: 'search_knowledge', arguments: args }
  })
});

const data = await res.json();
if (data.error) return 'MCP Error: ' + (data.error.message || JSON.stringify(data.error));
if (data.result?.content) {
  return data.result.content.map(c => c.type === 'text' ? c.text : JSON.stringify(c)).join('\n');
}
return JSON.stringify(data.result || data);

